class Solution:
    def scoreOfStudents(self, s: str, answers: List[int]) -> int:
        def values(i, j):
            if i == j:
                return {int(s[i])}
            res = set()
            for p in range(i + 1, j, 2):
                for a in values(i, p - 1):
                    for b in values(p + 1, j):
                        res.add(a + b if s[p] == '+' else a * b)
            return res

        term, correct = int(s[0]), 0
        for k in range(1, len(s), 2):
            if s[k] == '*':
                term *= int(s[k + 1])
            else:
                correct += term
                term = int(s[k + 1])
        correct += term
        possible = values(0, len(s) - 1)
        return sum(5 if x == correct else 2 if x in possible else 0 for x in answers)

