class Solution {
public:
    int scoreOfStudents(string s, vector<int>& answers) {
        int n = s.size();
        set<long long> possible;
        build(s, 0, n - 1, possible);
        long long correct = 0, term = s[0] - '0';
        for (int k = 1; k < n; k += 2) {
            if (s[k] == '*') term *= s[k + 1] - '0';
            else { correct += term; term = s[k + 1] - '0'; }
        }
        correct += term;
        int score = 0;
        for (int a : answers) {
            if (a == correct) score += 5;
            else if (possible.count(a)) score += 2;
        }
        return score;
    }
private:
    void build(const string& s, int i, int j, set<long long>& out) {
        if (i == j) { out.insert(s[i] - '0'); return; }
        for (int p = i + 1; p < j; p += 2) {
            set<long long> left, right;
            build(s, i, p - 1, left);
            build(s, p + 1, j, right);
            for (long long a : left)
                for (long long b : right)
                    out.insert(s[p] == '+' ? a + b : a * b);
        }
    }
};

